import sys; sys.path.insert(0,'/tmp/claude-0/rip'); from est import *
C='RIF'
E(C,'M1-Z01','La gerarchia dei rifiuti',[CL("Quale gradino della gerarchia?","Seleziona un intervento, poi il gradino della gerarchia dei rifiuti.",["Prevenzione","Preparazione per il riutilizzo","Riciclaggio","Recupero di altro tipo","Smaltimento"],[
 ["Imballaggi a rendere al posto di quelli monouso",0,"Evita che il rifiuto si formi."],["Riparazione e controllo di pallet danneggiati per rimetterli in uso",1,"È preparazione per il riutilizzo."],
 ["Rottami metallici avviati a fonderia",2,"La materia diventa nuova materia."],["Combustibile solido secondario usato in cementeria",3,"È recupero energetico."],
 ["Conferimento in discarica di scorie non recuperabili",4,"È l’ultima opzione."],["Riprogettazione del prodotto per usare meno materiale",0,"Riduce la quantità di rifiuti alla fonte."],
 ["Carta e cartone avviati a cartiera",2,"È riciclaggio."],["Incenerimento senza recupero di energia",4,"È smaltimento."]],
 "Otto interventi sui rifiuti. Collocali sul gradino giusto della gerarchia, dalla prevenzione allo smaltimento.","Art. 179 D.lgs. 152/2006")])
E(C,'M1-Z02','Sottoprodotti e cessazione della qualifica di rifiuto',[CL("Rifiuto, sottoprodotto o end of waste?","Seleziona un caso, poi la qualifica più probabile.",["Rifiuto","Sottoprodotto","End of waste"],[
 ["Trucioli di legno ceduti a un pannellificio con contratto, senza trattamenti",1,"Utilizzo certo e diretto, senza trattamenti diversi dalla normale pratica industriale."],
 ["Scarti di plastica mista accumulati senza un utilizzatore",0,"Manca la certezza dell’utilizzo: è un rifiuto."],
 ["Aggregato riciclato da rifiuti inerti che rispetta i criteri del decreto ministeriale",2,"È un rifiuto recuperato che ha cessato la qualifica."],
 ["Siero di latte venduto a un allevamento per l’alimentazione animale nel rispetto delle norme",1,"È un residuo con utilizzo certo e legale."],
 ["Rottame di vetro trattato secondo il regolamento europeo e venduto alla vetreria",2,"I criteri europei consentono la cessazione della qualifica."],
 ["Fanghi di verniciatura",0,"Sono rifiuti, spesso pericolosi."]],
 "Sei casi di residui di produzione. Stabilisci se sono rifiuti, sottoprodotti o materiali che hanno cessato la qualifica di rifiuto.","Artt. 184-bis e 184-ter D.lgs. 152/2006 · D.M. 264/2016")])
E(C,'M1-Z03','Rifiuti urbani e rifiuti speciali',[SC("I rifiuti dello stabilimento","Uno stabilimento metalmeccanico produce sfridi di lavorazione, imballaggi in cartone delle materie prime, rifiuti della mensa e carta degli uffici.",[
 ("Quali rifiuti sono urbani?",[["Tutti, perché sono prodotti nello stesso Comune",False,"Conta l’origine e la natura dei rifiuti."],["Quelli di mensa e uffici, simili per natura e composizione ai domestici",True,"Corretto: aree come uffici e mense producono rifiuti urbani."],["Nessuno",False,"Uffici e mense producono rifiuti simili ai domestici."]]),
 ("Gli sfridi di lavorazione sono…",[["Rifiuti speciali da lavorazioni industriali",True,"Corretto: derivano dall’attività produttiva."],["Rifiuti urbani",False,"Le lavorazioni industriali producono rifiuti speciali."],["Non sono rifiuti",False,"Lo sono, salvo che rispettino le condizioni del sottoprodotto."]]),
 ("L’impresa vuole conferire gli urbani a un recuperatore privato. Che cosa deve fare?",[["Nulla di particolare",False,"Serve dimostrare l’avvio a recupero."],["Conferirli al di fuori del servizio pubblico, dimostrandone l’avvio a recupero secondo le regole comunali e nazionali",True,"Corretto: le utenze non domestiche possono farlo, con la relativa documentazione."],["Bruciarli in loco",False,"La combustione di rifiuti è un reato."]])],
 "Uffici e mense producono urbani, la produzione produce speciali; chi esce dal servizio pubblico deve documentare l’avvio a recupero.","Uno stabilimento produce rifiuti diversi. Classificali correttamente.","Art. 183 e Allegati L-quater e L-quinquies D.lgs. 152/2006")])
E(C,'M1-Z04','Formulario di identificazione e registro di carico e scarico',[LB("Laboratorio · Il formulario con gli errori","Controlli un formulario prima che il mezzo lasci lo stabilimento.",[
  ["Rifiuto","«oli esausti», EER 13 02 05*, stato fisico liquido"],["Quantità","«circa un fusto»"],["Caratteristiche di pericolo","non indicate"],["Trasportatore","iscritto in categoria 4"],["Destinazione","impianto autorizzato R13"],["Firme","manca la firma del produttore"]],[
  ("Individua gli errori del formulario.",6,"Quantità non espressa in kg o litri e indicata come «circa»; caratteristiche di pericolo mancanti per un rifiuto pericoloso; trasportatore in categoria 4, non abilitata ai rifiuti pericolosi; manca la firma del produttore.",["Ho individuato la quantità imprecisa","Ho individuato le HP mancanti","Ho individuato categoria e firma"]),
  ("Che cosa fai prima della partenza?",6,"Si blocca la partenza: si pesa o si misura il rifiuto e si indica la quantità, si inseriscono le caratteristiche di pericolo, si sostituisce il trasportatore con uno in categoria 5 e si firma. Con il formulario digitale si emette un nuovo formulario corretto.",["Ho bloccato la partenza","Ho previsto le correzioni","Ho previsto un trasportatore abilitato"]),
  ("Chi risponde se il formulario parte con errori?",5,"Il produttore, per le indicazioni incomplete o inesatte del formulario (art. 258); il trasportatore non abilitato, per trasporto non autorizzato; il produttore anche per aver affidato i rifiuti a un soggetto non autorizzato.",["Ho indicato la responsabilità del produttore","Ho indicato quella del trasportatore","Ho collegato l’art. 258"])],
 "Nel laboratorio controlli un formulario prima della partenza del mezzo. Individua gli errori, decidi come intervenire e stabilisci chi ne risponderebbe, poi confronta le tue risposte con la soluzione di riferimento.","Artt. 188, 193 e 258 D.lgs. 152/2006 · D.M. 59/2023")])
E(C,'M1-Z05','Le esclusioni e la cancellazione dal registro',[SC("Il parrucchiere e l’estetista","Un centro estetico con 3 dipendenti produce aghi e materiali taglienti (EER 18 01 03*) e chiede se deve iscriversi al RENTRI.",[
 ("Deve iscriversi?",[["Sì, sempre, perché produce rifiuti pericolosi",False,"Alcune attività con codici ATECO specifici sono escluse."],["No, se l’attività rientra tra i codici ATECO esclusi, anche per l’EER 18 01 03*",True,"Corretto: è una delle esclusioni dell’art. 188-bis."],["Solo se supera 10 dipendenti",False,"Il criterio non è il numero di dipendenti."]]),
 ("Esclusa dal RENTRI, l’impresa non ha più obblighi?",[["Nessun obbligo",False,"Restano la corretta gestione e la consegna a soggetti autorizzati."],["Restano gli obblighi di corretta gestione e di consegna a soggetti autorizzati, con la documentazione prevista",True,"Corretto: l’esclusione riguarda il registro, non la gestione."],["Può gettare i rifiuti nell’indifferenziato",False,"È vietato."]]),
 ("Se l’impresa amplia l’attività e cambia codice ATECO, che cosa fa?",[["Verifica di nuovo se rientra tra gli obbligati",True,"Corretto: l’obbligo dipende dall’attività e dai rifiuti."],["Nulla",False,"Serve una nuova verifica."],["Si iscrive all’Albo",False,"Non è la conseguenza."]])],
 "Le esclusioni dal RENTRI dipendono da attività e rifiuti: vanno verificate e riverificate quando l’attività cambia, e non eliminano gli obblighi di corretta gestione.","Un piccolo centro estetico produce rifiuti sanitari. Verifica gli obblighi.","Art. 188-bis, c. 3-bis, D.lgs. 152/2006")])
E(C,'M1-Z06','Il MUD: soggetti obbligati e scadenze',[LB("Laboratorio · Preparare il MUD","Prepari la dichiarazione per una carpenteria con 25 dipendenti.",[
  ["Rifiuti dell’anno","sfridi di acciaio 17 t; imballaggi misti 4 t; oli esausti 0,6 t; filtri dell’olio 0,1 t"],["Fonti dei dati","registro di carico e scarico, formulari, quarte copie o conferme di accettazione"],["Destinatari","fonderia R4; impianto R13 per imballaggi; CONOU per oli"]],[
  ("La carpenteria è obbligata? Per quali rifiuti?",5,"Sì: produce rifiuti pericolosi, gli oli e i filtri, e rifiuti non pericolosi da lavorazioni industriali con più di 10 dipendenti. Dichiara quindi tutti i rifiuti prodotti.",["Ho riconosciuto i rifiuti pericolosi","Ho applicato la soglia dei 10 dipendenti","Ho concluso che dichiara tutti i rifiuti"]),
  ("Come controlli la coerenza dei dati prima dell’invio?",7,"Si confrontano le quantità di carico e scarico del registro con i formulari e le quantità accettate dagli impianti; si verificano le giacenze a fine anno; si controllano codici EER, destinatari e trasportatori; si correggono gli scostamenti documentando le cause.",["Ho previsto il confronto registro-formulari","Ho considerato le giacenze","Ho previsto la documentazione degli scostamenti"]),
  ("Entro quando e a chi si presenta? Che cosa cambierà con il RENTRI?",5,"Entro il 30 aprile, salvo proroghe, alla Camera di commercio competente, con il modello approvato per l’anno. Con il RENTRI la dichiarazione sarà progressivamente superata per gli iscritti, secondo le disposizioni attuative.",["Ho indicato il 30 aprile","Ho indicato la Camera di commercio","Ho citato il superamento progressivo"])],
 "Nel laboratorio prepari la dichiarazione annuale dei rifiuti di una carpenteria. Verifica l’obbligo, controlla la coerenza dei dati e indica termini e destinatario, poi confronta le tue risposte con la soluzione di riferimento.","L. 70/1994 · art. 189 D.lgs. 152/2006 · D.P.C.M. 30 gennaio 2026")])
E(C,'M2-Z01','Terre e rocce da scavo',[SC("Le terre del piccolo cantiere","Un’impresa scava 2.000 m³ di terreno per le fondazioni di un capannone. Vuole riutilizzarne una parte in un altro cantiere per un rilevato.",[
 ("Il terreno riutilizzato nello stesso sito è un rifiuto?",[["No, se non è contaminato ed è riutilizzato allo stato naturale nello stesso sito",True,"Corretto: è escluso dalla disciplina dei rifiuti."],["Sì, sempre",False,"C’è un’esclusione specifica."],["Dipende dal colore",False,"Contano la contaminazione e il riutilizzo."]]),
 ("Per portarlo in un altro cantiere come sottoprodotto, che cosa serve?",[["La dichiarazione di utilizzo almeno 15 giorni prima dell’inizio dei lavori, essendo un cantiere fino a 6.000 m³",True,"Corretto: è la procedura per i cantieri di piccole dimensioni."],["Il piano di utilizzo approvato dalla Regione",False,"È per i cantieri di grandi dimensioni soggetti a VIA o AIA."],["Nulla",False,"Servono la dichiarazione e il rispetto dei requisiti."]]),
 ("Le analisi rivelano idrocarburi oltre le concentrazioni soglia. Che cosa succede?",[["Il terreno si gestisce come rifiuto con codice EER 17 05 e si attivano le procedure previste per la contaminazione",True,"Corretto: senza i requisiti non può essere sottoprodotto."],["Si mescola con terra pulita",False,"La diluizione è vietata."],["Si riutilizza lo stesso",False,"Non è ammesso."]])],
 "Riutilizzo nel sito solo se non contaminato, dichiarazione di utilizzo per i piccoli cantieri, gestione come rifiuto senza requisiti: le terre e rocce da scavo seguono regole precise.","Le terre di scavo di un piccolo cantiere. Decidi come gestirle.","D.P.R. 120/2017, artt. 21 e 24")])
E(C,'M2-Z02','Rifiuti contenenti amianto',[SC("Le lastre sul tetto del capannone","Il proprietario di un capannone vuole sostituire la copertura in lastre di cemento-amianto deteriorate.",[
 ("A chi affida i lavori?",[["A un’impresa iscritta all’Albo gestori ambientali in categoria 10",True,"Corretto: la bonifica di beni contenenti amianto richiede l’iscrizione in categoria 10."],["A qualsiasi impresa edile",False,"Serve un’impresa abilitata."],["Ai propri dipendenti",False,"Servono requisiti e formazione specifici."]]),
 ("Quando possono iniziare i lavori?",[["Subito",False,"Il piano di lavoro va presentato prima."],["Non prima di 30 giorni dalla presentazione del piano di lavoro all’organo di vigilanza",True,"Corretto: art. 256 del D.lgs. 81/2008."],["Dopo il permesso dei vicini",False,"Non è il requisito."]]),
 ("Come sono gestite le lastre rimosse?",[["Come rifiuto pericoloso 17 06 05*, confezionato, etichettato e avviato in discarica autorizzata",True,"Corretto."],["Frantumate e usate come riempimento",False,"Frantumare l’amianto libera fibre ed è vietato."],["Lasciate nel piazzale",False,"È un deposito incontrollato."]])],
 "Impresa in categoria 10, piano di lavoro almeno 30 giorni prima, rifiuto pericoloso confezionato e smaltito in discarica autorizzata: la rimozione dell’amianto è una filiera controllata.","Una copertura in cemento-amianto da rimuovere. Organizza i lavori.","Art. 256 D.lgs. 81/2008 · art. 212 D.lgs. 152/2006")])
E(C,'M2-Z03','Flussi particolari: oli usati, RAEE, imballaggi',[CL("Quale disciplina?","Seleziona un rifiuto o prodotto, poi la disciplina di riferimento.",["Oli usati","RAEE","Imballaggi","Batterie"],[
 ["Olio esausto del cambio dei carrelli",0,"Deposito separato e conferimento tramite il consorzio CONOU."],["Monitor dismessi degli uffici",1,"Apparecchiature elettriche ed elettroniche: D.lgs. 49/2014."],
 ["Pallet in legno e film estensibile",2,"Imballaggi: Reg. (UE) 2025/40."],["Accumulatori al litio dei carrelli",3,"Reg. (UE) 2023/1542."],
 ["Frigorifero della mensa da sostituire",1,"È un RAEE; per il ritiro valgono anche le regole dell’uno contro uno."],["Fusti metallici vuoti delle materie prime",2,"Sono imballaggi."]],
 "Sei rifiuti o prodotti a fine vita. Individua la disciplina speciale di riferimento.","D.lgs. 49/2014 · Reg. (UE) 2025/40 · Reg. (UE) 2023/1542")])
E(C,'M2-Z04','Il regime sanzionatorio dei rifiuti',[LB("Laboratorio · Il controllo in azienda","Un controllo in un’impresa di lavorazione della plastica si chiude con quattro rilievi.",[
  ["Rilievo 1","rifiuti di plastica e fanghi accumulati da 14 mesi in un’area non pavimentata"],["Rilievo 2","formulari con codici EER non corrispondenti ai rifiuti effettivi"],["Rilievo 3","conferimenti a un trasportatore non iscritto all’Albo"],["Rilievo 4","residui di imballaggi bruciati in un fusto nel piazzale"]],[
  ("Qualifica ciascun rilievo indicando l’articolo di riferimento.",7,"1: oltre i limiti del deposito temporaneo e senza condizioni tecniche: deposito incontrollato o gestione non autorizzata (artt. 255-256). 2: violazione degli obblighi del formulario (art. 258), con rilievo penale se i dati sulla natura del rifiuto sono falsi. 3: trasporto non autorizzato (art. 256) e responsabilità del produttore che ha affidato i rifiuti. 4: combustione illecita di rifiuti (art. 256-bis).",["Ho qualificato tutti e quattro i rilievi","Ho citato gli articoli corretti","Ho considerato la responsabilità del produttore"],None,120),
  ("Quali rilievi possono coinvolgere anche l’ente ai sensi del D.lgs. 231/2001?",5,"Diversi reati in materia di rifiuti, tra cui la gestione non autorizzata, sono reati presupposto dell’art. 25-undecies: se commessi nell’interesse o a vantaggio dell’impresa, ad esempio per risparmiare sui costi, risponde anche l’ente.",["Ho collegato l’art. 25-undecies","Ho richiamato interesse o vantaggio"]),
  ("Proponi un piano di rientro in ordine di priorità.",7,"Subito: cessare la combustione e la consegna al trasportatore non iscritto; avviare a recupero o smaltimento i rifiuti accumulati con soggetti autorizzati. Entro poche settimane: classificazione corretta e analisi dei fanghi; correzione dei formulari futuri; pavimentazione e organizzazione del deposito. Poi: procedura di qualifica dei fornitori, formazione, controlli periodici.",["Ho messo in ordine le priorità","Ho previsto il ricorso a soggetti autorizzati","Ho previsto procedure e formazione"],None,120)],
 "Nel laboratorio analizzi i rilievi di un controllo in un’impresa che lavora la plastica. Qualifica i rilievi, individua quelli che possono coinvolgere l’ente e proponi un piano di rientro, poi confronta ogni risposta con la soluzione di riferimento.","Artt. 255, 256, 256-bis e 258 D.lgs. 152/2006 · art. 25-undecies D.lgs. 231/2001")])
E(C,'M2-Z05','Esercitazione · La quarta copia che non arriva',[LB("Laboratorio · Il piano di gestione dei rifiuti","Riassumi in un piano la gestione dei rifiuti di un’impresa metalmeccanica con 30 dipendenti.",[
  ["Rifiuti","sfridi metallici, emulsioni oleose esauste, oli, imballaggi, fanghi dal lavaggio pezzi"],["Organizzazione","nessun responsabile designato; ritiri a chiamata"],["Obiettivo","conformità e riduzione dei costi"]],[
  ("Classifica i rifiuti e indica per ciascuno la destinazione preferibile secondo la gerarchia.",8,"Sfridi metallici, non pericolosi, a riciclaggio in fonderia; emulsioni oleose esauste, di norma pericolose, a trattamento chimico-fisico; oli tramite CONOU per la rigenerazione; imballaggi a riciclaggio o riutilizzo; fanghi da classificare con analisi, a recupero o smaltimento autorizzato. Prima ancora: ridurre emulsioni e fanghi con manutenzione e filtrazione.",["Ho distinto pericolosi e non pericolosi","Ho applicato la gerarchia","Ho previsto interventi di prevenzione"],None,150),
  ("Definisci ruoli e controlli.",6,"Un responsabile della gestione dei rifiuti con delega e budget; calendario dei ritiri coerente con il criterio del deposito temporaneo; verifica iniziale e periodica di trasportatori e impianti; controllo mensile dei formulari aperti e delle accettazioni; formazione degli addetti.",["Ho designato un responsabile","Ho previsto il controllo della filiera","Ho previsto la formazione"]),
  ("Indica tre indicatori per misurare il miglioramento.",5,"Quantità di rifiuti per unità di prodotto; percentuale avviata a recupero sul totale; numero di non conformità documentali per trimestre. Facoltativo: costo di gestione per tonnellata.",["Ho proposto un indicatore di quantità","Ho proposto un indicatore di recupero","Ho proposto un indicatore di conformità"])],
 "Il laboratorio conclude il corso: scrivi un piano di gestione dei rifiuti per un’impresa metalmeccanica. Classifica i rifiuti con le destinazioni preferibili, definisci ruoli e controlli e proponi tre indicatori, poi confronta ogni risposta con la soluzione di riferimento.","Artt. 179, 183, 185-bis e 188 D.lgs. 152/2006"),
 AP("La gestione dei rifiuti nella tua azienda","Verifica la gestione dei rifiuti nella tua organizzazione.",["I rifiuti sono classificati con i codici EER","Il deposito temporaneo rispetta le condizioni","Il criterio di avvio è scritto","Trasportatori e impianti sono verificati","Le accettazioni sono controllate","Il MUD o il RENTRI sono gestiti","Esiste un responsabile designato"],"La prima azione che proporresti","Es.: verifica dell’iscrizione all’Albo di tutti i trasportatori entro un mese",
  "Verifica come la tua azienda gestisce i rifiuti e indica la prima azione che proporresti.",3)])
E(C,'M1-Z07','Rifiuti pericolosi: caratteristiche HP e procedura di classificazione',[SC("Il rifiuto senza analisi","Un’impresa produce da anni polveri di sabbiatura che smaltisce con il codice non pericoloso 12 01 17, senza alcuna analisi. Il nuovo responsabile ambiente ha dei dubbi.",[
 ("Che tipo di voce è 12 01 17?",[["Una voce a specchio, accoppiata a 12 01 16* per i residui contenenti sostanze pericolose",True,"Corretto: la scelta del codice richiede di conoscere la composizione."],["Una voce assoluta non pericolosa",False,"Ha una voce speculare pericolosa."],["Una voce che non esiste",False,"Esiste nell’elenco europeo."]]),
 ("Che cosa fai?",[["Continui come prima",False,"Senza caratterizzazione la classificazione non è dimostrata."],["Ricostruisci il processo, individui le sostanze pertinenti, come i metalli delle vernici rimosse, e fai analizzare un campione rappresentativo",True,"Corretto: è la procedura di classificazione."],["Passi d’ufficio al codice pericoloso senza verifiche",False,"È prudente ma va comunque motivato: la caratterizzazione serve."]]),
 ("Le analisi rilevano piombo oltre la soglia di una caratteristica di pericolo. Che cosa cambia?",[["Il codice diventa 12 01 16*, con tutti gli obblighi per i rifiuti pericolosi",True,"Corretto: iscrizione al RENTRI, deposito, trasporto e destinazione adeguati."],["Nulla, conta il codice storico",False,"Il codice deve corrispondere al rifiuto reale."],["Solo il prezzo dello smaltimento",False,"Cambiano anche gli obblighi."]])],
 "Le voci a specchio richiedono di conoscere il rifiuto: storia del processo, sostanze pertinenti, analisi e confronto con le soglie HP decidono il codice e gli obblighi.","Un rifiuto classificato da anni senza analisi. Verifica la classificazione.","Decisione 2014/955/UE · Reg. (UE) 1357/2014 · Linee guida SNPA")])
E(C,'M2-Z06','Rifiuti pericolosi e trasporto ADR',[SC("I fusti in partenza","Devono partire 12 fusti di solventi esausti infiammabili, rifiuto pericoloso, verso un impianto autorizzato.",[
 ("Il trasporto ricade nell’ADR?",[["Sì, se il rifiuto è una merce pericolosa secondo i criteri ADR: classificazione, imballaggi, etichette e documenti ADR si aggiungono agli obblighi dei rifiuti",True,"Corretto: le due discipline si sommano."],["No, i rifiuti non sono mai merci pericolose",False,"I rifiuti pericolosi possono esserlo."],["Basta il formulario",False,"Servono anche le indicazioni ADR."]]),
 ("Chi verifica gli adempimenti ADR in azienda?",[["Il consulente per la sicurezza dei trasporti di merci pericolose, quando l’impresa vi è tenuta",True,"Corretto: assiste l’impresa nelle operazioni di carico, imballaggio e trasporto."],["Il medico competente",False,"Non è il suo ruolo."],["Nessuno",False,"Serve una figura competente."]]),
 ("Un fusto ha il coperchio deformato e perde. Che cosa fai?",[["Lo carichi lo stesso, il viaggio è breve",False,"Un imballaggio danneggiato non si carica."],["Lo travasi in un imballaggio omologato integro, lo etichetti e aggiorni i documenti",True,"Corretto: l’integrità dell’imballaggio è un requisito essenziale."],["Lo copri con un telo",False,"Non risolve la perdita."]])],
 "Rifiuti pericolosi e merci pericolose sono due discipline che si sommano: imballaggi integri e omologati, etichette, documenti e consulente ADR quando previsto.","Fusti di solventi infiammabili da spedire. Verifica il trasporto.","ADR · art. 193 D.lgs. 152/2006"),
 VF("Ripasso · Gestione dei rifiuti",[["Il produttore resta responsabile se affida i rifiuti a un trasportatore non iscritto all’Albo.",True,"Vero: deve verificare autorizzazioni e iscrizioni."],["Le emulsioni oleose si possono miscelare con gli oli usati per semplificare il ritiro.",False,"Falso: gli oli usati vanno depositati separatamente, senza miscelazioni."],["Le terre e rocce da scavo contaminate possono essere riutilizzate come sottoprodotto.",False,"Falso: senza requisiti sono rifiuti."],["La combustione illecita di rifiuti è un reato.",True,"Vero: art. 256-bis."]],"Ripasso: quattro affermazioni sulla gestione dei rifiuti.","D.lgs. 152/2006, Parte IV")])
